CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE roles (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    name character varying(64) NOT NULL,
    description character varying(256),
    is_active boolean NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT pk_roles PRIMARY KEY (id)
);

CREATE TABLE subscription_plans (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    name character varying(50) NOT NULL,
    display_name character varying(100) NOT NULL,
    max_users integer NOT NULL,
    max_projects integer NOT NULL,
    price_monthly numeric(10,2) NOT NULL,
    price_yearly numeric(10,2) NOT NULL,
    trial_duration_days integer NOT NULL,
    is_active boolean NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT pk_subscription_plans PRIMARY KEY (id)
);

CREATE TABLE tenants (
    id uuid NOT NULL,
    name character varying(150) NOT NULL,
    slug character varying(80) NOT NULL,
    is_active boolean NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT pk_tenants PRIMARY KEY (id)
);

CREATE TABLE users (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    username character varying(64) NOT NULL,
    email character varying(256) NOT NULL,
    normalized_email character varying(256) NOT NULL,
    password_hash character varying(512) NOT NULL,
    security_stamp character varying(128) NOT NULL,
    first_name character varying(64),
    last_name character varying(64),
    phone_number character varying(20),
    avatar_url character varying(500),
    is_active boolean NOT NULL,
    is_email_confirmed boolean NOT NULL,
    is_two_factor_enabled boolean NOT NULL,
    two_factor_secret_key character varying(256),
    lockout_end timestamp with time zone,
    access_failed_count integer NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    last_login_at_utc timestamp with time zone,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT fk_users_tenants_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);

CREATE TABLE email_verification_tokens (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    token_hash character varying(512) NOT NULL,
    expires_at_utc timestamp with time zone NOT NULL,
    is_used boolean NOT NULL,
    used_at_utc timestamp with time zone,
    created_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT pk_email_verification_tokens PRIMARY KEY (id),
    CONSTRAINT fk_email_verification_tokens_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE login_audit_logs (
    id bigint GENERATED BY DEFAULT AS IDENTITY,
    user_id uuid,
    email_attempted character varying(256) NOT NULL,
    ip_address character varying(45),
    user_agent character varying(1024),
    login_result character varying(20) NOT NULL,
    failure_reason character varying(256),
    attempted_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT pk_login_audit_logs PRIMARY KEY (id),
    CONSTRAINT fk_login_audit_logs_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE password_reset_tokens (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    token_hash character varying(512) NOT NULL,
    expires_at_utc timestamp with time zone NOT NULL,
    is_used boolean NOT NULL,
    used_at_utc timestamp with time zone,
    created_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT pk_password_reset_tokens PRIMARY KEY (id),
    CONSTRAINT fk_password_reset_tokens_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE refresh_tokens (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    token_hash character varying(512) NOT NULL,
    device_info character varying(512),
    ip_address character varying(45),
    created_at_utc timestamp with time zone NOT NULL,
    expires_at_utc timestamp with time zone NOT NULL,
    revoked_at_utc timestamp with time zone,
    replaced_by_token_hash character varying(512),
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT fk_refresh_tokens_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE subscriptions (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    plan_id integer NOT NULL,
    status character varying(20) NOT NULL,
    trial_start_at_utc timestamp with time zone,
    trial_end_at_utc timestamp with time zone,
    subscription_start_at_utc timestamp with time zone NOT NULL,
    subscription_end_at_utc timestamp with time zone,
    cancelled_at_utc timestamp with time zone,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT pk_subscriptions PRIMARY KEY (id),
    CONSTRAINT fk_subscriptions_subscription_plans_plan_id FOREIGN KEY (plan_id) REFERENCES subscription_plans (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscriptions_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE user_roles (
    user_id uuid NOT NULL,
    role_id integer NOT NULL,
    assigned_at_utc timestamp with time zone NOT NULL,
    assigned_by_user_id uuid,
    CONSTRAINT pk_user_roles PRIMARY KEY (user_id, role_id),
    CONSTRAINT fk_user_roles_roles_role_id FOREIGN KEY (role_id) REFERENCES roles (id) ON DELETE CASCADE,
    CONSTRAINT fk_user_roles_users_assigned_by_user_id FOREIGN KEY (assigned_by_user_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_roles_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE user_sessions (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    session_token_hash character varying(512) NOT NULL,
    device_info character varying(512),
    ip_address character varying(45),
    created_at_utc timestamp with time zone NOT NULL,
    expires_at_utc timestamp with time zone NOT NULL,
    last_activity_at_utc timestamp with time zone NOT NULL,
    is_revoked boolean NOT NULL,
    CONSTRAINT pk_user_sessions PRIMARY KEY (id),
    CONSTRAINT fk_user_sessions_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_email_verification_tokens_token_hash ON email_verification_tokens (token_hash);

CREATE INDEX ix_email_verification_tokens_user_id ON email_verification_tokens (user_id);

CREATE INDEX ix_login_audit_logs_user_id_attempted_at_utc ON login_audit_logs (user_id, attempted_at_utc DESC);

CREATE INDEX ix_password_reset_tokens_token_hash ON password_reset_tokens (token_hash);

CREATE INDEX ix_password_reset_tokens_user_id ON password_reset_tokens (user_id);

CREATE INDEX ix_refresh_tokens_token_hash ON refresh_tokens (token_hash);

CREATE INDEX ix_refresh_tokens_user_id ON refresh_tokens (user_id);

CREATE UNIQUE INDEX ix_roles_name ON roles (name);

CREATE UNIQUE INDEX ix_subscription_plans_name ON subscription_plans (name);

CREATE INDEX ix_subscriptions_plan_id ON subscriptions (plan_id);

CREATE INDEX ix_subscriptions_user_id ON subscriptions (user_id);

CREATE UNIQUE INDEX ix_tenants_slug ON tenants (slug);

CREATE INDEX ix_user_roles_assigned_by_user_id ON user_roles (assigned_by_user_id);

CREATE INDEX ix_user_roles_role_id ON user_roles (role_id);

CREATE INDEX ix_user_sessions_session_token_hash ON user_sessions (session_token_hash);

CREATE INDEX ix_user_sessions_user_id ON user_sessions (user_id);

CREATE INDEX ix_users_normalized_email ON users (normalized_email);

CREATE UNIQUE INDEX ix_users_tenant_id_normalized_email ON users (tenant_id, normalized_email);

CREATE UNIQUE INDEX ix_users_tenant_id_username ON users (tenant_id, username);

