    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT pk_payroll_runs PRIMARY KEY (id),
    CONSTRAINT fk_payroll_runs_payroll_parameters_parameters_id FOREIGN KEY (parameters_id) REFERENCES payroll_parameters (id) ON DELETE RESTRICT,
    CONSTRAINT fk_payroll_runs_tenants_tenant_id FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);

